[Expected Solution] Using Monotonic Stack - O(n) Time and O(n) SpaceThe idea is to use a monotonic decreasing stack. We traverse the array from left to right. For each element, we pop elements from the stack that are smaller than or equal to it, since they cannot be the previous greater element. If the stack is not empty, the top of the stack is the previous greater element. Finally, we push the current element onto the stack.
            C++

    #include <iostream>
#include <vector>
#include <stack>
using namespace std;

vector<int> preGreaterEle(vector<int>& arr) {
    int n = arr.size();

    // initialize all PGEs as -1
    vector<int> result(n, -1); 

    // stack to keep track of elements
    stack<int> st; 

    // traverse the array from left to right
    for (int i = 0; i < n; i++) {

        // pop elements from stack which are <= current element
        while (!st.empty() && st.top() <= arr[i]) {
            st.pop();
        }

        // if stack is not empty, top element is PGE
        if (!st.empty()) {
            result[i] = st.top();
        }

        // push current element onto stack
        st.push(arr[i]);
    }

    return result;
}

int main() {
    vector<int> arr = {10, 4, 2, 20, 40, 12};
    vector<int> pge = preGreaterEle(arr);

    for (int x : pge) {
        cout << x << " ";
    }
    cout << endl;

    return 0;
}


            Java

    import java.util.ArrayList;
import java.util.Stack;
import java.util.Collections;

class Solution {
    static ArrayList<Integer> preGreaterEle(int[] arr) {
        int n = arr.length;

        // initialize all PGEs as -1
        ArrayList<Integer> result = new ArrayList<>(Collections.nCopies(n, -1));

        // stack to keep track of elements
        Stack<Integer> st = new Stack<>();

        // traverse the array from left to right
        for (int i = 0; i < n; i++) {

            // pop elements from stack which are <= current element
            while (!st.isEmpty() && st.peek() <= arr[i]) {
                st.pop();
            }

            // if stack is not empty, top element is PGE
            if (!st.isEmpty()) {
                result.set(i, st.peek());
            }

            // push current element onto stack
            st.push(arr[i]);
        }

        return result;
    }

    public static void main(String[] args) {
        int[] arr = {10, 4, 2, 20, 40, 12};
        ArrayList<Integer> pge = preGreaterEle(arr);

        for (int x : pge) {
            System.out.print(x + " ");
        }
        System.out.println();
    }
}


